cd /workspace && PYTHONHASHSEED=0 python3 -c "
import sys; sys.path.insert(0,'/workspace')
from program_model import load_all_benchmarks
ps = load_all_benchmarks('/workspace/benchmarks')
libm=0; libmb=0; appm=0; appmb=0; phantom_cls=set(); phantom_m=set(); libflows=0
for p in ps:
    names={c.name for c in p.classes}
    ref=set()
    for c in p.classes:
        if c.super_class: ref.add(c.super_class)
        ref.update(c.interfaces)
        for m in c.methods:
            if c.is_library: libm+=1; libmb += 1 if m.body else 0
            else: appm+=1; appmb += 1 if m.body else 0
            if m.body:
                for s in m.body.statements:
                    if s.callee: ref.add(s.callee.class_name)
    for r in ref-names-{'java.lang.Object'}: phantom_cls.add((p.name,r))
    # phantom methods: callee sigs not declared
    decl={m.signature.full_signature() for c in p.classes for m in c.methods}
    for c in p.classes:
        for m in c.methods:
            if m.body:
                for s in m.body.statements:
                    if s.callee and s.callee.full_signature() not in decl:
                        phantom_m.add((p.name,s.callee.full_signature()))
    # summarizable library flows
    for c in p.classes:
        if not c.is_library: continue
        for m in c.methods:
            if not m.body: continue
            for s in m.body.statements:
                if s.kind=='field_store' or (s.kind=='field_load'): libflows+=1
print('lib methods',libm,'with body',libmb,'app methods',appm,'with body',appmb)
print('phantom classes',len(phantom_cls)); [print('   ',x) for x in sorted(phantom_cls)]
print('phantom methods',len(phantom_m)); [print('   ',x) for x in sorted(phantom_m)]
print('lib field ops (proxy for flows)',libflows)
"
